  'پایش در خانه — فرم خانواده (نسخهٔ ۲)',
  'بیست‌وچهار مشاهدهٔ کوتاه خانه‌به‌خانه در هشت کانون — دقیقاً همان هشت سازه‌ای که در «جمع‌بندی تشخیصی» پروندهٔ فرزند شما ردیابی می‌شود (توجه و کارکرد اجرایی، رفتارهای برون‌ریزی، حال و هیجان، زبان و ارتباط، یادگیری درسی، هماهنگی حرکتی، شناخت عمومی، مهارت‌های اجتماعی و خودیاری). هنگام ارسال، کانون‌های درگیرِ پروندهٔ او در ابتدای فرم علامت می‌خورند تا نگاه شما متمرکز شود. پاسخ درست یا غلط ندارد؛ وضعیت دو هفتهٔ اخیر را ملاک بگیرید. حدود ۷ دقیقه وقت می‌برد.',
  'checklist',
  '🏠',
  1,
  '[{"key":"hm_att1","label":"برای شروع و تمام کردن کاری که دوست ندارد (تکلیف، جمع‌کردن وسایل) به یادآوری مدام شما نیاز دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"attention_exec"},{"key":"hm_att2","label":"وسط کارش حواسش پرت می‌شود و از موضوع دور می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"attention_exec"},{"key":"hm_att3","label":"وسایلش را گم می‌کند یا جای آنها را به یاد نمی‌آورد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"attention_exec"},{"key":"hm_ext1","label":"با کوچک‌ترین منع، عصبانیتش ناگهان بالا می‌گیرد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"externalizing"},{"key":"hm_ext2","label":"با خواهر/برادر یا هم‌بازی‌هاش درگیری لفظی یا فیزیکی دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"externalizing"},{"key":"hm_ext3","label":"قانون را می‌شناسد اما نقض می‌کند و به تذکر بی‌اعتناست","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"externalizing"},{"key":"hm_int1","label":"از جدا شدن از شما یا رفتن به جای تازه نگران و چسبنده می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"internalizing"},{"key":"hm_int2","label":"بیش‌ازحد نگران اشتباه کردن یا آینده است؛ پیش از رویدادها سردرد یا دل‌درد می‌گیرد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"internalizing"},{"key":"hm_int3","label":"از فعالیت‌هایی که قبلاً دوست داشت کناره می‌گیرد و خلوت‌تر شده است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"internalizing"},{"key":"hm_lng1","label":"کلمهٔ مورد نظرش را به یاد نمی‌آورد و کلمهٔ دور و درازی می‌گوید","type":"scale","scaleMax":3,"scaleLabel