فه لازم دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"general_cog"},{"key":"hm_cog3","label":"در کارهای چندقدمی روزمره (آماده‌کردن کیف، ترتیب کارها) گم می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"general_cog"},{"key":"hm_soc1","label":"در بازی گروهی قواعد نانوشته را نمی‌فهمد و از بازی کنار گذاشته می‌شود","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"social_adl"},{"key":"hm_soc2","label":"کارهای روزمرهٔ خودش (لباس، غذا، کیفش) به یادآوری شما نیاز دارد","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"social_adl"},{"key":"hm_soc3","label":"در سلام‌واحوال‌پرسی و گفت‌وگوی دوستانه کم‌رنگ و دوری‌گزین است","type":"scale","scaleMax":3,"scaleLabels":["اصلاً","کم","متوسط","زیاد"],"required":true,"subscaleId":"social_adl"},{"key":"hm_note","label":"توضیحات — نمونهٔ مشخصی از رفتار، زمان یا موقعیتی که نگران‌تان کرده (اختیاری)","type":"longtext","required":false}]',
