  'ce-center-survey-v1',
  'نظرسنجی رضایت — مرکز و درمانگر',
  'ده جملهٔ کوتاه دربارهٔ تجربهٔ شما از مرکز و درمانگر فرزندتان + یک پرسش توصیه به آشنایان. پاسخ شما بی‌نام بررسی می‌شود و مستقیم در «شاخص‌های عملکردی مرکز» می‌نشیند؛ فقط متن پیشنهاد شما با نام خودتان به مدیر می‌رسد. حدود ۳ دقیقه وقت می‌برد.',
  'checklist',
  '📋',
  1,
  '[{"key":"sv_cen1","label":"برخورد پذیرش و کارشناسان مرکز با شما و فرزندتان","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"center"},{"key":"sv_cen2","label":"رعایت زمان نوبت‌ها و نظم برنامه","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"center"},{"key":"sv_cen3","label":"اطلاع‌رسانی، پاسخ‌گویی تلفن و پیام‌ها و پیگیری کارها","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"center"},{"key":"sv_cen4","label":"نظافت، آرامش و کودک‌پسند بودن فضای مرکز","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"center"},{"key":"sv_cen5","label":"رضایت کلی شما از مرکز","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"center"},{"key":"sv_thr1","label":"ایجاد ارتباط و اعتماد درمانگر با فرزند شما","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"therapist"},{"key":"sv_thr2","label":"آموزش‌هایی که به شما می‌دهد (تمرین خانگی، راهنمایی والد)","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"therapist"},{"key":"sv_thr3","label":"گزارش‌دادن پیشرفت فرزند و شفافیت گفت‌وگوها","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"therapist"},{"key":"sv_thr4","label":"رعایت وقت جلسه‌ها و تعهد کاری درمانگر","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"therapist"},{"key":"sv_thr5","label":"پیشرفتی که در فرزندتان مشاهده کرده‌اید","type":"scale","scaleMax":4,"scaleLabels":["خیلی ضعیف","ضعیف","متوسط","خوب","عالی"],"required":true,"subscaleId":"therapist"},{"key":"sv_nps","label":"چقدر احتمال دارد مرکز ما را به آشنایانتان