-- ب) غیرفعال‌سازی نرم فرم‌های تکراری/کم‌ارزش (داده‌های قبلی و رویدادهای ثبت‌شده دست‌نخورده می‌مانند)
UPDATE case_event_types SET active = 0, updated_at = updated_at
WHERE key IN ('legacy_assessment', 'quick-multi-v1', 'sdq-parent', 'home_behavior') AND active = 1;
